import {useCallback,useEffect,useMemo,useState} from 'react';
import {Activity,ArrowLeft,Download,FileText,HeartPulse,RefreshCw,ShieldCheck,TestTube2,TrendingUp,UserRound,Utensils} from 'lucide-react';
import {downloadFiteatsyConnectionReport,getFiteatsyConnection,getFiteatsyConnectionHealthContext} from '../../lib/practiceOperationsApi';

const NAV=['Overview','Health','Nutrition & Care','Progress','Documents & Admin'];
const HEALTH_NAV=['Health profile','Biomarkers','Health records','Measurements','Reports'];
const present=value=>value!==null&&value!==undefined&&value!=='';
const object=value=>value&&typeof value==='object'&&!Array.isArray(value)?value:{};
const array=value=>Array.isArray(value)?value:[];
const words=value=>String(value||'').replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' ').replaceAll('-',' ').replace(/\b\w/g,letter=>letter.toUpperCase());
const date=value=>{if(!value)return 'Not shared';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?String(value):new Intl.DateTimeFormat('en-IN',{dateStyle:'medium'}).format(parsed);};
const text=value=>{if(!present(value))return 'Not shared';if(typeof value==='boolean')return value?'Yes':'No';if(Array.isArray(value))return value.length?value.map(item=>typeof item==='object'?Object.values(item).filter(present).join(' · '):String(item)).join(', '):'None recorded';return String(value);};

function Empty({title,detail}){return <div className="rounded-2xl border border-dashed border-slate-300 bg-slate-50 p-6 text-center"><p className="font-bold text-slate-800">{title}</p><p className="mt-2 text-sm text-slate-500">{detail}</p></div>;}
function Field({label,value}){return <div className="rounded-2xl bg-slate-50 p-4"><dt className="text-xs font-bold uppercase tracking-wider text-slate-500">{label}</dt><dd className="mt-2 break-words text-sm font-semibold text-slate-900">{text(value)}</dd></div>;}
function FieldGrid({items}){return <dl className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{items.filter(item=>present(item.value)).map(item=><Field key={item.label} {...item}/>)}</dl>;}
function Card({title,icon:Icon,children}){return <section className="rounded-3xl border border-slate-200 bg-white p-5 shadow-sm sm:p-6"><div className="mb-5 flex items-center gap-2">{Icon&&<Icon size={20} className="text-blue-700"/>}<h3 className="text-lg font-bold text-slate-950">{title}</h3></div>{children}</section>;}
function Metric({label,value,detail,tone='blue'}){const tones={blue:'bg-blue-50 text-blue-700',emerald:'bg-emerald-50 text-emerald-700',rose:'bg-rose-50 text-rose-700',violet:'bg-violet-50 text-violet-700'};return <div className={`rounded-2xl p-4 ${tones[tone]}`}><p className="text-xs font-bold uppercase tracking-wider opacity-70">{label}</p><p className="mt-2 text-2xl font-bold">{value}</p>{detail&&<p className="mt-1 text-xs opacity-75">{detail}</p>}</div>;}

export function ConnectedFiteatsyClient360({client,onBack}){
  const [state,setState]=useState({loading:true,data:null,error:''});
  const [section,setSection]=useState('Overview');
  const [healthSection,setHealthSection]=useState('Health profile');
  const connectionId=client?.connectionId;
  const load=useCallback(async()=>{if(!connectionId){setState({loading:false,data:null,error:'This client has no active consented connection. Health data remains unavailable.'});return;}setState({loading:true,data:null,error:''});try{const [healthContext,careLedger]=await Promise.all([getFiteatsyConnectionHealthContext(connectionId),getFiteatsyConnection(connectionId)]);setState({loading:false,data:{...healthContext,careLedger},error:''});}catch(error){setState({loading:false,data:null,error:error.message||'The consented Fiteatsy client context could not be loaded.'});}},[connectionId]);
  useEffect(()=>{load();},[load]);
  const profile=object(state.data?.profile?.client),onboarding=object(state.data?.profile?.onboarding),healthProfile=object(state.data?.profile?.healthProfile);
  const measurements=object(state.data?.measurements),wearables=object(state.data?.wearables),biomarkers=array(state.data?.biomarkers),reports=array(state.data?.reports),careLedger=object(state.data?.careLedger);
  const programmes=array(careLedger.programmes),planPublications=array(careLedger.plan_publications),appointments=array(careLedger.appointments),connection=object(careLedger.connection);
  const lifestyle=object(onboarding.lifestyle),nutrition=object(onboarding.nutrition),history=object(onboarding.healthHistory),metrics=array(wearables.latestMetrics);
  const name=profile.name||client?.displayName||'Connected Fiteatsy client';
  const connectedRecently=useMemo(()=>client?.connectedAt&&Date.now()-new Date(client.connectedAt).getTime()<7*24*60*60*1000,[client?.connectedAt]);
  const abnormal=biomarkers.filter(item=>['HIGH','LOW','CRITICAL','ABNORMAL'].includes(String(item.clinicalStatus).toUpperCase()));
  const bmi=Number(measurements.heightCm)>0&&Number(measurements.weightKg)>0?(Number(measurements.weightKg)/(Number(measurements.heightCm)/100)**2).toFixed(1):null;
  const download=async report=>{try{const file=await downloadFiteatsyConnectionReport(connectionId,report.id);const url=URL.createObjectURL(file.blob);const link=document.createElement('a');link.href=url;link.download=file.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){setState(current=>({...current,error:error.message||'The report could not be downloaded.'}));}};
  const reportsView=<Card title="Health reports" icon={FileText}>{reports.length?<div className="grid gap-3">{reports.map(report=><button key={report.id} type="button" onClick={()=>download(report)} className="flex min-h-14 items-center justify-between rounded-2xl border border-slate-200 px-4 text-left hover:bg-slate-50"><span><strong className="block text-sm text-slate-900">{report.originalFilename||report.fileName||words(report.reportType)||'Health report'}</strong><small className="mt-1 block text-slate-500">{date(report.reportDate||report.uploadedAt)} · {words(report.processingStatus||'Available')}</small></span><Download size={18} className="text-slate-500"/></button>)}</div>:<Empty title="No shared reports" detail="No health report is available within the client's approved scopes."/>}</Card>;

  const healthContent=()=>{
    if(healthSection==='Biomarkers')return <Card title={`Biomarkers (${biomarkers.length})`} icon={TestTube2}>{biomarkers.length?<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{biomarkers.map((marker,index)=><article key={marker.biomarkerId||`${marker.name}-${index}`} className="rounded-2xl border border-slate-200 p-4"><div className="flex items-start justify-between gap-3"><div><h4 className="font-bold text-slate-950">{marker.name||marker.canonicalMarkerName||'Biomarker'}</h4><p className="mt-2 text-2xl font-bold">{text(marker.value)} <span className="text-sm font-semibold text-slate-500">{marker.unit}</span></p></div><span className={`rounded-full px-2.5 py-1 text-xs font-bold ${String(marker.clinicalStatus).toUpperCase()==='NORMAL'?'bg-emerald-100 text-emerald-800':'bg-amber-100 text-amber-900'}`}>{words(marker.clinicalStatus||marker.validationStatus)}</span></div><dl className="mt-4 space-y-2 text-xs text-slate-600"><div className="flex justify-between gap-3"><dt>Reference</dt><dd className="font-semibold text-slate-800">{text(marker.referenceRange)}</dd></div><div className="flex justify-between gap-3"><dt>Test date</dt><dd className="font-semibold text-slate-800">{date(marker.testDate)}</dd></div><div className="flex justify-between gap-3"><dt>Source</dt><dd className="font-semibold text-slate-800">{marker.source?.label||'Not shared'}</dd></div>{present(marker.previousValue)&&<div className="flex justify-between gap-3"><dt>Previous</dt><dd className="font-semibold text-slate-800">{marker.previousValue} {marker.previousUnit||marker.unit}</dd></div>}</dl></article>)}</div>:<Empty title="No consented biomarkers" detail="Validated biomarker results will appear after a report is analysed and shared."/>}</Card>;
    if(healthSection==='Measurements')return <Card title="Measurements" icon={Activity}><FieldGrid items={[{label:'Height',value:measurements.heightCm&&`${measurements.heightCm} cm`},{label:'Weight',value:measurements.weightKg&&`${measurements.weightKg} kg`},{label:'BMI',value:bmi},{label:'Age',value:measurements.age||profile.age},{label:'Gender',value:measurements.gender||profile.gender},{label:'Activity level',value:measurements.activityLevel||onboarding.activityLevel}]}/>{metrics.length>0&&<div className="mt-6 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{metrics.map(metric=><Metric key={metric.metricType} label={words(metric.metricType)} value={`${metric.latestValue} ${metric.unit}`} detail={`${date(metric.measuredAt)} · ${words(metric.sourceProvider)}`} tone="emerald"/>)}</div>}</Card>;
    if(healthSection==='Reports')return reportsView;
    if(healthSection==='Health records')return reports.length?<Card title="Dated health records" icon={FileText}><div className="space-y-3">{reports.map(report=><div key={report.id} className="rounded-2xl border p-4"><p className="text-xs font-bold uppercase tracking-wider text-blue-700">{words(report.reportType||'Lab analysis')}</p><p className="mt-2 font-bold">{report.labName||report.originalFilename||'Health report'}</p><p className="mt-1 text-sm text-slate-500">{date(report.reportDate||report.uploadedAt)} · {array(report.biomarkers).length} observations</p></div>)}</div></Card>:<Empty title="No dated health records" detail="Records appear when a consented health report is available."/>;
    return <div className="grid gap-5 lg:grid-cols-2"><Card title="Clinical profile" icon={HeartPulse}><FieldGrid items={[{label:'Goal',value:onboarding.goal},{label:'Medical conditions',value:onboarding.medicalConditions},{label:'Medications',value:history.medications},{label:'Family history',value:history.familyMedicalHistory},{label:'Previous conditions',value:history.previousConditions},{label:'Previous surgeries',value:history.previousSurgeries}]}/></Card><Card title="Latest health signals" icon={Activity}>{metrics.length?<div className="grid gap-3 sm:grid-cols-2">{metrics.map(metric=><Metric key={metric.metricType} label={words(metric.metricType)} value={`${metric.latestValue} ${metric.unit}`} detail={date(metric.measuredAt)} tone="violet"/>)}</div>:<Empty title="No synced device signals" detail="No consented wearable measurement is currently available."/>}</Card></div>;
  };

  const content=()=>{
    if(section==='Health')return <><nav className="mb-5 flex gap-2 overflow-x-auto rounded-2xl border bg-white p-2" aria-label="Health sections">{HEALTH_NAV.map(item=><button key={item} type="button" onClick={()=>setHealthSection(item)} className={`min-h-11 whitespace-nowrap rounded-xl px-4 text-sm font-bold ${healthSection===item?'bg-slate-950 text-white':'text-slate-600 hover:bg-slate-100'}`}>{item}</button>)}</nav>{healthContent()}</>;
    if(section==='Nutrition & Care')return <div className="grid gap-5 lg:grid-cols-2"><Card title="Nutrition profile" icon={Utensils}><FieldGrid items={[{label:'Dietary preference',value:nutrition.dietaryPreference},{label:'Preferred cuisines',value:nutrition.preferredCuisines},{label:'Food allergies',value:nutrition.foodAllergies},{label:'Food dislikes',value:nutrition.foodDislikes},{label:'Meal frequency',value:nutrition.mealFrequency},{label:'Water intake',value:nutrition.waterIntakeLiters&&`${nutrition.waterIntakeLiters} L`}]}/></Card><Card title="Care context" icon={HeartPulse}><FieldGrid items={[{label:'Primary goal',value:onboarding.goal},{label:'Conditions',value:onboarding.medicalConditions},{label:'Medications',value:history.medications},{label:'Sleep',value:lifestyle.sleepHours&&`${lifestyle.sleepHours} hours`},{label:'Stress level',value:lifestyle.stressLevel},{label:'Exercise frequency',value:lifestyle.exerciseFrequency}]}/></Card><Card title={`Care programmes (${programmes.length})`} icon={TrendingUp}>{programmes.length?<div className="space-y-3">{programmes.map(programme=><div key={programme.id} className="rounded-2xl border border-slate-200 p-4"><div className="flex justify-between gap-3"><strong>{programme.name}</strong><span className="rounded-full bg-blue-50 px-2.5 py-1 text-xs font-bold text-blue-700">{words(programme.status)}</span></div><p className="mt-2 text-xs text-slate-500">{date(programme.starts_on)} – {date(programme.ends_on)}</p></div>)}</div>:<Empty title="No care programme yet" detail="Programmes created for this consented connection will appear here."/>}</Card><Card title={`Published diet plans (${planPublications.length})`} icon={FileText}>{planPublications.length?<div className="space-y-3">{planPublications.map(plan=><div key={plan.id} className="rounded-2xl border border-slate-200 p-4"><div className="flex justify-between gap-3"><strong>{plan.title||'Diet plan'}</strong><span className="rounded-full bg-emerald-50 px-2.5 py-1 text-xs font-bold text-emerald-700">{words(plan.status)}</span></div><p className="mt-2 text-xs text-slate-500">Version {text(plan.plan_version)} · Published {date(plan.published_at)}</p></div>)}</div>:<Empty title="No published diet plan" detail="Plans published through this connection will appear here; none is inferred from profile data."/>}</Card><Card title={`Appointments (${appointments.length})`} icon={FileText}>{appointments.length?<div className="space-y-3">{appointments.map(appointment=><div key={appointment.id} className="rounded-2xl border border-slate-200 p-4"><div className="flex justify-between gap-3"><strong>{appointment.title||'Appointment'}</strong><span className="rounded-full bg-violet-50 px-2.5 py-1 text-xs font-bold text-violet-700">{words(appointment.status)}</span></div><p className="mt-2 text-xs text-slate-500">{date(appointment.starts_at)}{appointment.ends_at?` – ${date(appointment.ends_at)}`:''}</p></div>)}</div>:<Empty title="No appointments scheduled" detail="Appointments created for this connection will appear here."/>}</Card></div>;
    if(section==='Progress')return <div className="grid gap-5 lg:grid-cols-2"><Card title="Clinical progress" icon={TrendingUp}>{biomarkers.some(item=>present(item.previousValue))?<div className="grid gap-3">{biomarkers.filter(item=>present(item.previousValue)).slice(0,12).map(item=><div key={item.biomarkerId} className="flex items-center justify-between rounded-2xl bg-slate-50 p-4"><span><strong className="block">{item.name}</strong><small className="text-slate-500">{date(item.previousTestDate)} → {date(item.testDate)}</small></span><span className="font-bold">{item.previousValue} → {item.value} {item.unit}</span></div>)}</div>:<Empty title="Baseline captured" detail="Trend comparisons appear after a biomarker has more than one dated observation."/>}</Card><Card title="Activity progress" icon={Activity}>{metrics.length?<div className="grid gap-3 sm:grid-cols-2">{metrics.map(metric=><Metric key={metric.metricType} label={words(metric.metricType)} value={`${metric.latestValue} ${metric.unit}`} detail={`${metric.acceptedRecords||1} accepted records`} tone="blue"/>)}</div>:<Empty title="No activity history" detail="No approved activity measurements are available."/>}</Card></div>;
    if(section==='Documents & Admin')return <div className="space-y-5">{reportsView}<Card title="Access governance" icon={ShieldCheck}><FieldGrid items={[{label:'Connection status',value:connection.state||'Active'},{label:'Connected on',value:date(connection.connected_at||client?.connectedAt)},{label:'Consent version',value:connection.consent_version},{label:'Approved scopes',value:connection.consented_scopes},{label:'Programme status',value:connection.programme_status},{label:'Connection ID',value:connectionId},{label:'Generated at',value:date(state.data?.generatedAt)},{label:'Reports shared',value:reports.length},{label:'Biomarkers shared',value:biomarkers.length}]}/><p className="mt-5 text-sm text-slate-500">Only scopes approved by this client are displayed. Revoking consent immediately removes access.</p></Card></div>;
    return <div className="space-y-5"><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><Metric label="Profile" value={healthProfile.profileCompleted?'Complete':'In progress'} detail={profile.accountStatus||profile.status} tone="blue"/><Metric label="Biomarkers" value={biomarkers.length} detail={`${abnormal.length} need attention`} tone="rose"/><Metric label="Reports" value={reports.length} detail={`Updated ${date(healthProfile.lastHealthUpdate)}`} tone="violet"/><Metric label="Health records" value={wearables.recordsCount||0} detail={wearables.connected?'Device source connected':'No device source'} tone="emerald"/></div><div className="grid gap-5 lg:grid-cols-2"><Card title="Client profile" icon={UserRound}><FieldGrid items={[{label:'Name',value:name},{label:'Age',value:profile.age},{label:'Gender',value:profile.gender},{label:'Date of birth',value:date(profile.dob)},{label:'Email',value:profile.email},{label:'Mobile',value:profile.mobileNumberMasked}]}/></Card><Card title="Health snapshot" icon={HeartPulse}><FieldGrid items={[{label:'Goal',value:onboarding.goal},{label:'Activity level',value:onboarding.activityLevel},{label:'Height',value:measurements.heightCm&&`${measurements.heightCm} cm`},{label:'Weight',value:measurements.weightKg&&`${measurements.weightKg} kg`},{label:'BMI',value:bmi},{label:'Conditions',value:onboarding.medicalConditions}]}/></Card></div>{abnormal.length>0&&<Card title="Needs attention" icon={TestTube2}><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{abnormal.slice(0,6).map(item=><div key={item.biomarkerId} className="rounded-2xl bg-amber-50 p-4"><p className="font-bold text-amber-950">{item.name}</p><p className="mt-2 text-xl font-bold text-amber-900">{item.value} {item.unit}</p><p className="mt-1 text-xs text-amber-800">{words(item.clinicalStatus)} · ref {text(item.referenceRange)}</p></div>)}</div></Card>}</div>;
  };

  return <section><button type="button" onClick={onBack} className="mb-5 inline-flex min-h-11 items-center gap-2 rounded-xl px-2 text-sm font-bold text-slate-600 hover:bg-slate-100"><ArrowLeft size={17}/>Back to clients</button><div className="overflow-hidden rounded-3xl border border-slate-200 bg-slate-50 shadow-sm"><header className="bg-gradient-to-br from-slate-950 via-blue-950 to-cyan-900 p-6 text-white sm:p-8"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.18em] text-cyan-300">Client 360 · consent controlled</p><h2 className="mt-2 text-3xl font-bold">{name}</h2><p className="mt-2 text-sm text-blue-100">Live, connection-scoped Fiteatsy context</p></div><span className="inline-flex items-center gap-2 rounded-full border border-emerald-300/30 bg-emerald-400/15 px-3 py-2 text-xs font-bold text-emerald-100"><ShieldCheck size={16}/>{connectedRecently?'Newly connected':'Connected'}</span></div></header>{state.loading?<div className="p-12 text-center text-sm text-slate-500">Loading authorised client data…</div>:state.error?<div className="m-6 rounded-2xl border border-red-200 bg-red-50 p-5" role="alert"><p className="font-bold text-red-900">Client data unavailable</p><p className="mt-2 text-sm text-red-800">{state.error}</p><button type="button" onClick={load} className="mt-4 inline-flex min-h-11 items-center gap-2 rounded-xl bg-red-900 px-4 text-sm font-bold text-white"><RefreshCw size={16}/>Retry</button></div>:<div className="p-4 sm:p-6"><nav className="mb-6 flex gap-2 overflow-x-auto rounded-2xl border border-slate-200 bg-white p-2" aria-label="Client 360 sections">{NAV.map(item=><button key={item} type="button" onClick={()=>setSection(item)} className={`min-h-11 whitespace-nowrap rounded-xl px-4 text-sm font-bold ${section===item?'bg-slate-950 text-white':'text-slate-600 hover:bg-slate-100'}`}>{item}</button>)}</nav>{content()}</div>}</div></section>;
}
